targets.query:
from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "io.systemd.Basic.MemoryUsedBytes" and r._field == "value" and r.host == "${host}")

from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "io.systemd.Basic.PhysicalMemoryBytes" and r._field == "value" and r.host == "${host}")

from(bucket: "${bucket}")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "io.systemd.Basic.SwapUsedBytes" and r._field == "value" and r.host == "${host}")

